package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct { // 01 LEDGER-REC, 14 bytes
	BrBranch string          // PIC X(2) @0 len=2
	BrAcct   string          // PIC X(4) @2 len=4
	BrType   string          // PIC X(1) @6 len=1
	BrAmt    decimal.Decimal // PIC 9(5)V99 @7 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsFirstFlag string // PIC X len=1 = "Y"
var WsPrevBranch string // PIC X(2) len=2 = SPACES
var WsPrevAcct string // PIC X(4) len=4 = SPACES
var WsBal decimal.Decimal // PIC S9(7)V99 len=9 = 0
var WsBranchTot decimal.Decimal // PIC S9(9)V99 len=11 = 0
var WsGrandTot decimal.Decimal // PIC S9(9)V99 len=11 = 0
var WsSkipped int64 // PIC 99 len=2 = 0
var WsAmtEd string // PIC ZZ,ZZ9.99 len=9
var WsBalEd string // PIC -Z,ZZZ,ZZ9.99 len=13
var WsTotEd string // PIC -ZZZ,ZZZ,ZZ9.99 len=15

var CurLedgerRec LedgerRec
var ledgerLines []string
var ledgerIdx int

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func display(parts ...string) {
	s := strings.Join(parts, "")
	os.Stdout.WriteString(s + "\n")
}

func storeBal(d decimal.Decimal) decimal.Decimal {
	t := d.Truncate(2)
	scaled := t.Shift(2).Truncate(0).IntPart()
	const mod int64 = 1000000000 // 10^9
	r := scaled % mod
	return decimal.New(r, -2)
}

func storeTot(d decimal.Decimal) decimal.Decimal {
	t := d.Truncate(2)
	scaled := t.Shift(2).Truncate(0).IntPart()
	const mod int64 = 100000000000 // 10^11
	r := scaled % mod
	return decimal.New(r, -2)
}

func formatAmtEd(d decimal.Decimal) string {
	t := d.Truncate(2)
	a := t.Abs()
	scaled := a.Shift(2).Truncate(0).IntPart()
	intPart := scaled / 100
	fracPart := scaled % 100
	if fracPart < 0 {
		fracPart = -fracPart
	}
	if intPart < 0 {
		intPart = -intPart
	}
	mod := intPart % 100000
	var digits [5]int64
	tmp := mod
	for i := 4; i >= 0; i-- {
		// extract least significant first
		digits[i] = tmp % 10
		tmp /= 10
	}
	// recompute correctly: above loop is wrong order? fix by re-extract:
	// Actually the loop above puts LSD at index 4 correctly.
	fracTens := fracPart / 10
	fracOnes := fracPart % 10
	first := -1
	for i, v := range digits {
		if v != 0 {
			first = i
			break
		}
	}
	var out [9]byte
	// Z positions
	zIdx := []int{0, 1, 3, 4}
	zDig := []int{0, 1, 2, 3}
	for k, pos := range zIdx {
		di := zDig[k]
		if first == -1 || di < first {
			out[pos] = ' '
		} else {
			out[pos] = byte('0' + digits[di])
		}
	}
	// 9 position
	out[5] = byte('0' + digits[4])
	// comma
	if first != -1 && first <= 1 {
		out[2] = ','
	} else {
		out[2] = ' '
	}
	out[6] = '.'
	out[7] = byte('0' + fracTens)
	out[8] = byte('0' + fracOnes)
	return string(out[:])
}

func formatBalEd(d decimal.Decimal) string {
	t := d.Truncate(2)
	neg := t.Sign() < 0
	a := t.Abs()
	scaled := a.Shift(2).Truncate(0).IntPart()
	intPart := scaled / 100
	fracPart := scaled % 100
	mod := intPart % 10000000
	var digits [7]int64
	tmp := mod
	for i := 6; i >= 0; i-- {
		digits[i] = tmp % 10
		tmp /= 10
	}
	fracTens := fracPart / 10
	fracOnes := fracPart % 10
	first := -1
	for i, v := range digits {
		if v != 0 {
			first = i
			break
		}
	}
	var out [13]byte
	if neg {
		out[0] = '-'
	} else {
		out[0] = ' '
	}
	// map digit index to pos
	posMap := []int{1, 3, 4, 5, 7, 8, 9}
	for di, pos := range posMap {
		if di == 6 {
			// 9 position always prints
			out[pos] = byte('0' + digits[di])
		} else {
			if first == -1 || di < first {
				out[pos] = ' '
			} else {
				out[pos] = byte('0' + digits[di])
			}
		}
	}
	if first != -1 && first <= 0 {
		out[2] = ','
	} else {
		out[2] = ' '
	}
	if first != -1 && first <= 3 {
		out[6] = ','
	} else {
		out[6] = ' '
	}
	out[10] = '.'
	out[11] = byte('0' + fracTens)
	out[12] = byte('0' + fracOnes)
	return string(out[:])
}

func formatTotEd(d decimal.Decimal) string {
	t := d.Truncate(2)
	neg := t.Sign() < 0
	a := t.Abs()
	scaled := a.Shift(2).Truncate(0).IntPart()
	intPart := scaled / 100
	fracPart := scaled % 100
	mod := intPart % 1000000000
	var digits [9]int64
	tmp := mod
	for i := 8; i >= 0; i-- {
		digits[i] = tmp % 10
		tmp /= 10
	}
	fracTens := fracPart / 10
	fracOnes := fracPart % 10
	first := -1
	for i, v := range digits {
		if v != 0 {
			first = i
			break
		}
	}
	var out [15]byte
	if neg {
		out[0] = '-'
	} else {
		out[0] = ' '
	}
	posMap := []int{1, 2, 3, 5, 6, 7, 9, 10, 11}
	for di, pos := range posMap {
		if di == 8 {
			out[pos] = byte('0' + digits[di])
		} else {
			if first == -1 || di < first {
				out[pos] = ' '
			} else {
				out[pos] = byte('0' + digits[di])
			}
		}
	}
	if first != -1 && first <= 2 {
		out[4] = ','
	} else {
		out[4] = ' '
	}
	if first != -1 && first <= 5 {
		out[8] = ','
	} else {
		out[8] = ' '
	}
	out[12] = '.'
	out[13] = byte('0' + fracTens)
	out[14] = byte('0' + fracOnes)
	return string(out[:])
}

func ReadPara() {
	if ledgerIdx >= len(ledgerLines) {
		WsEofFlag = "Y"
		return
	}
	line := ledgerLines[ledgerIdx]
	ledgerIdx++
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	} else if len(line) > 14 {
		line = line[:14]
	}
	CurLedgerRec.BrBranch = line[0:2]
	CurLedgerRec.BrAcct = line[2:6]
	CurLedgerRec.BrType = line[6:7]
	amtStr := line[7:14]
	var n int64
	for i := 0; i < len(amtStr); i++ {
		c := amtStr[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else {
			n = n * 10
		}
	}
	CurLedgerRec.BrAmt = decimal.New(n, -2)
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevBranch = CurLedgerRec.BrBranch
		WsPrevAcct = CurLedgerRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if CurLedgerRec.BrBranch != WsPrevBranch {
			AcctBreakPara()
			BranchBreakPara()
			WsPrevBranch = CurLedgerRec.BrBranch
			WsPrevAcct = CurLedgerRec.BrAcct
		} else {
			if CurLedgerRec.BrAcct != WsPrevAcct {
				AcctBreakPara()
				WsPrevAcct = CurLedgerRec.BrAcct
			}
		}
	}
	PostPara()
	ReadPara()
}

func PostPara() {
	WsAmtEd = formatAmtEd(CurLedgerRec.BrAmt)
	switch CurLedgerRec.BrType {
	case "D":
		WsBal = storeBal(WsBal.Add(CurLedgerRec.BrAmt))
		display(CurLedgerRec.BrAcct, " D ", WsAmtEd)
	case "C":
		WsBal = storeBal(WsBal.Sub(CurLedgerRec.BrAmt))
		display(CurLedgerRec.BrAcct, " C ", WsAmtEd)
	default:
		WsSkipped = (WsSkipped + 1) % 100
		display(CurLedgerRec.BrAcct, " ? SKIPPED")
	}
}

func AcctBreakPara() {
	WsBalEd = formatBalEd(WsBal)
	display("  ACCOUNT ", WsPrevAcct, " BALANCE:", WsBalEd)
	WsBranchTot = storeTot(WsBranchTot.Add(WsBal))
	WsBal = decimal.New(0, 0)
}

func BranchBreakPara() {
	WsTotEd = formatTotEd(WsBranchTot)
	display(" BRANCH ", WsPrevBranch, " TOTAL:", WsTotEd)
	WsGrandTot = storeTot(WsGrandTot.Add(WsBranchTot))
	WsBranchTot = decimal.New(0, 0)
}

func GrandPara() {
	WsTotEd = formatTotEd(WsGrandTot)
	display("GRAND TOTAL:", WsTotEd)
	sk := WsSkipped % 100
	if sk < 0 {
		sk += 100
	}
	skStr := fmt.Sprintf("%02d", sk)
	display("SKIPPED: ", skStr)
}

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevBranch = "  "
	WsPrevAcct = "    "
	WsBal = decimal.New(0, 0)
	WsBranchTot = decimal.New(0, 0)
	WsGrandTot = decimal.New(0, 0)
	WsSkipped = 0

	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			ledgerLines = []string{}
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		scanner := bufio.NewScanner(f)
		var lines []string
		for scanner.Scan() {
			lines = append(lines, scanner.Text())
		}
		if serr := scanner.Err(); serr != nil {
			fmt.Fprintln(os.Stderr, serr)
			f.Close()
			os.Exit(1)
		}
		f.Close()
		ledgerLines = lines
		if ledgerLines == nil {
			ledgerLines = []string{}
		}
	}
	ledgerIdx = 0

	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		AcctBreakPara()
		BranchBreakPara()
	}
	GrandPara()
}
